1	import { AxiosError, AxiosHeaders, InternalAxiosRequestConfig } from 'axios';
2	import { ErrorCodeEnum } from '@roombook/contract';
3	import type { ErrorResponseDto } from '@roombook/contract';
4	import { apiClient } from './api-client';
5	import { ApiError } from './api-error';
6	
7	const rejectingAdapter = (status: number, data: unknown) => (config: InternalAxiosRequestConfig) =>
8	  Promise.reject(
9	    new AxiosError('Request failed', AxiosError.ERR_BAD_REQUEST, config, null, {
10	      status,
11	      statusText: '',
12	      data,
13	      headers: {},
14	      config: { ...config, headers: new AxiosHeaders() },
15	    }),
16	  );
17	
18	describe('apiClient', () => {
19	  it('takes its base URL from NEXT_PUBLIC_API_URL', async () => {
20	    const original = process.env.NEXT_PUBLIC_API_URL;
21	    process.env.NEXT_PUBLIC_API_URL = 'http://api.test/api';
22	
23	    await jest.isolateModulesAsync(async () => {
24	      const { apiClient: freshClient } = await import('./api-client');
25	      expect(freshClient.defaults.baseURL).toBe('http://api.test/api');
26	    });
27	
28	    if (original === undefined) delete process.env.NEXT_PUBLIC_API_URL;
29	    else process.env.NEXT_PUBLIC_API_URL = original;
30	  });
31	
32	  it('turns an error response into an ApiError carrying the contract fields', async () => {
33	    const body: ErrorResponseDto = {
34	      statusCode: 404,
35	      errorCode: ErrorCodeEnum.ROOM_NOT_FOUND,
36	      message: 'Room not found',
37	    };
38	
39	    const failure = await apiClient.get('/rooms/x', { adapter: rejectingAdapter(404, body) }).catch((e: unknown) => e);
40	
41	    expect(failure).toBeInstanceOf(ApiError);
42	    expect(failure).toMatchObject(body);
43	  });
44	
45	  it('rethrows an error that has no response', async () => {
46	    const networkError = new AxiosError('Network Error', AxiosError.ERR_NETWORK);
47	
48	    const failure = await apiClient
49	      .get('/rooms', { adapter: () => Promise.reject(networkError) })
50	      .catch((e: unknown) => e);
51	
52	    expect(failure).toBe(networkError);
53	  });
54	});
