9	jest.mock('../../services/room.service', () => ({ listRooms: jest.fn() }));
10	
11	const mockedListRooms = listRooms as jest.MockedFunction<typeof listRooms>;
12	
13	const seededRooms: RoomDto[] = Array.from({ length: 12 }, (_, index) => {
14	  const number = String(index + 1).padStart(2, '0');
15	  return { id: `00000000-0000-4000-8000-0000000000${number}`, name: `Room ${number}`, capacity: (index + 1) * 2 };
16	});
17	
18	const pageOf = (page: number, limit: number): PagedRoomsDto => ({
19	  items: seededRooms.slice((page - 1) * limit, page * limit),
20	  total: seededRooms.length,
21	  page,
22	  limit,
23	});
24	
25	const bodyRows = () => within(screen.getByRole('table', { name: 'Rooms' })).getAllByRole('row').slice(1);
26	
27	describe('RoomsPage', () => {
28	  beforeEach(() => {
29	    mockedListRooms.mockReset();
30	    mockedListRooms.mockImplementation((page, limit) => Promise.resolve(pageOf(page, limit)));
31	  });
32	
33	  it('shows a loading indicator, then the 10 rows returned for page 1', async () => {
34	    render(<RoomsPage />);
35	
36	    expect(screen.getByRole('progressbar')).toBeInTheDocument();
37	    expect(await screen.findByText('Room 10')).toBeInTheDocument();
38	    expect(mockedListRooms).toHaveBeenCalledWith(1, 10);
39	    expect(bodyRows()).toHaveLength(10);
40	    expect(screen.queryByRole('progressbar')).not.toBeInTheDocument();
41	  });
42	
43	  it('requests page 2 with limit 5 after choosing 5 per page and going to the next page', async () => {
44	    const user = userEvent.setup();
45	    render(<RoomsPage />);
46	    await screen.findByText('Room 10');
47	
48	    await user.click(screen.getByRole('combobox', { name: /rows per page/i }));
49	    await user.click(screen.getByRole('option', { name: '5' }));
50	    await waitFor(() => expect(mockedListRooms).toHaveBeenLastCalledWith(1, 5));
51	    await waitFor(() => expect(bodyRows()).toHaveLength(5));
52	
53	    await user.click(screen.getByRole('button', { name: /next page/i }));
54	
55	    await waitFor(() => expect(mockedListRooms).toHaveBeenLastCalledWith(2, 5));
56	    expect(await screen.findByText('Room 06')).toBeInTheDocument();
57	  });
58	
59	  it('shows the ApiError message when the request is rejected', async () => {
60	    mockedListRooms.mockRejectedValue(
61	      new ApiError({
62	        statusCode: 503,
63	        errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE,
64	        message: 'Room service is unavailable',
65	      }),
66	    );
67	    render(<RoomsPage />);
68	
69	    expect(await screen.findByRole('alert')).toHaveTextContent('Room service is unavailable');
70	    expect(screen.queryByRole('table', { name: 'Rooms' })).not.toBeInTheDocument();
71	  });
72	});
