4	import { NEVER, Observable, of, throwError } from 'rxjs';
5	import { NatsRequestUtil } from './nats-request.util';
6	
7	const clientReturning = (result: Observable<unknown>): { client: ClientProxy; send: jest.Mock } => {
8	  const send = jest.fn().mockReturnValue(result);
9	  return { client: { send } as unknown as ClientProxy, send };
10	};
11	
12	const errorOf = async (promise: Promise<unknown>): Promise<unknown> =>
13	  promise.then(
14	    () => undefined,
15	    (error) => error,
16	  );
17	
18	describe('NatsRequestUtil.send', () => {
19	  afterEach(() => jest.useRealTimers());
20	
21	  it('resolves with the reply of the pattern', async () => {
22	    const { client, send } = clientReturning(of({ status: 'ok' }));
23	
24	    await expect(NatsRequestUtil.send(client, 'health:room', {})).resolves.toEqual({ status: 'ok' });
25	    expect(send).toHaveBeenCalledWith('health:room', {});
26	  });
27	
28	  it('rejects with a 503 once the reply takes longer than 5 seconds, without retrying', async () => {
29	    jest.useFakeTimers();
30	    const { client, send } = clientReturning(NEVER);
31	
32	    const pending = errorOf(NatsRequestUtil.send(client, 'health:room', {}));
33	    jest.advanceTimersByTime(5000);
34	    const error = await pending;
35	
36	    expect(error).toBeInstanceOf(RpcException);
37	    expect((error as RpcException).getError()).toEqual(
38	      expect.objectContaining({ statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE }),
39	    );
40	    expect(send).toHaveBeenCalledTimes(1);
41	  });
42	
43	  it('rejects with a 503 when no service listens to the pattern', async () => {
44	    const { client } = clientReturning(throwError(() => new EmptyResponseException('health:room')));
45	
46	    const error = await errorOf(NatsRequestUtil.send(client, 'health:room', {}));
47	
48	    expect((error as RpcException).getError()).toEqual(
49	      expect.objectContaining({ statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE }),
50	    );
51	  });
52	
53	  it('passes a domain error from the service through unchanged', async () => {
54	    const domainError = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' };
55	    const { client } = clientReturning(throwError(() => domainError));
