1	import { Injectable } from '@nestjs/common';
2	import { InjectRepository } from '@nestjs/typeorm';
3	import { RoomEntity } from '@roombook/backend-common';
4	import { DEFAULT_PAGE_SIZE, PagedRoomsDto, PageQueryDto, RoomDto } from '@roombook/contract';
5	import { Repository } from 'typeorm';
6	
7	const toRoomDto = (entity: RoomEntity): RoomDto => ({
8	  id: entity.id,
9	  name: entity.name,
10	  capacity: entity.capacity,
11	});
12	
13	@Injectable()
14	export class RoomRepository {
15	  constructor(@InjectRepository(RoomEntity) private readonly rooms: Repository<RoomEntity>) {}
16	
17	  async findPage(query: PageQueryDto): Promise<PagedRoomsDto> {
18	    const [entities, total] = await this.rooms.findAndCount({
19	      skip: (query.page - 1) * DEFAULT_PAGE_SIZE,
20	      take: query.limit,
21	      order: { name: 'ASC' },
22	    });
23	    return { items: entities.map(toRoomDto), total, page: query.page, limit: query.limit };
24	  }
25	
26	  async findById(id: string): Promise<RoomDto | null> {
27	    const entity = await this.rooms.findOneBy({ id });
28	    return entity ? toRoomDto(entity) : null;
29	  }
30	}
