import { ConfirmationStatusEnum } from '@roombook/contract';
import type { BookingDto, CreateBookingDto, PagedBookingsDto } from '@roombook/contract';
import { apiClient } from './api-client';
import { createBooking, deleteBooking, listBookings, updateBooking } from './booking.service';

jest.mock('./api-client', () => ({
  apiClient: { get: jest.fn(), post: jest.fn(), patch: jest.fn(), delete: jest.fn() },
}));

const mockedGet = apiClient.get as jest.Mock;
const mockedPost = apiClient.post as jest.Mock;
const mockedPatch = apiClient.patch as jest.Mock;
const mockedDelete = apiClient.delete as jest.Mock;

const ROOM_ID = '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10';
const BOOKING_ID = '7a1d2c3b-0000-4000-8000-000000000001';
const KEY = '11111111-1111-4111-8111-111111111111';

const body: CreateBookingDto = {
  roomId: ROOM_ID,
  title: 'Sprint planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
};

const booking: BookingDto = {
  ...body,
  id: BOOKING_ID,
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

describe('booking service', () => {
  beforeEach(() => jest.resetAllMocks());

  it('listBookings requests GET /bookings with page, limit and roomId and returns the body', async () => {
    const paged: PagedBookingsDto = { items: [booking], total: 1, page: 2, limit: 10 };
    mockedGet.mockResolvedValue({ data: paged });

    const result = await listBookings({ page: 2, limit: 10, roomId: ROOM_ID });

    expect(mockedGet).toHaveBeenCalledWith('/bookings', { params: { page: 2, limit: 10, roomId: ROOM_ID } });
    expect(result).toEqual(paged);
  });

  it('listBookings sends no roomId parameter when none is given', async () => {
    mockedGet.mockResolvedValue({ data: { items: [], total: 0, page: 1, limit: 10 } });

    await listBookings({ page: 1, limit: 10 });

    expect(mockedGet.mock.calls[0][1]).toStrictEqual({ params: { page: 1, limit: 10 } });
  });

  it('createBooking posts the body with the Idempotency-Key header and returns the booking', async () => {
    mockedPost.mockResolvedValue({ data: booking });

    const result = await createBooking(body, KEY);

    expect(mockedPost).toHaveBeenCalledWith('/bookings', body, { headers: { 'Idempotency-Key': KEY } });
    expect(result).toEqual(booking);
  });

  it('updateBooking patches /bookings/:id with only the given fields and returns the booking', async () => {
    mockedPatch.mockResolvedValue({ data: { ...booking, title: 'Retro' } });

    const result = await updateBooking(BOOKING_ID, { title: 'Retro' });

    expect(mockedPatch).toHaveBeenCalledWith(`/bookings/${BOOKING_ID}`, { title: 'Retro' });
    expect(result.title).toBe('Retro');
  });

  it('deleteBooking requests DELETE /bookings/:id', async () => {
    mockedDelete.mockResolvedValue({ data: '' });

    await expect(deleteBooking(BOOKING_ID)).resolves.toBeUndefined();

    expect(mockedDelete).toHaveBeenCalledWith(`/bookings/${BOOKING_ID}`);
  });

  it('propagates a rejected request', async () => {
    const failure = new Error('boom');
    mockedPost.mockRejectedValue(failure);

    await expect(createBooking(body, KEY)).rejects.toBe(failure);
  });
});

import { formatUtc, isoToUtcInput, parseUtcInput, utcInputToIso } from './utc-date-time';

describe('utc-date-time', () => {
  const originalTz = process.env.TZ;

  afterEach(() => {
    if (originalTz === undefined) delete process.env.TZ;
    else process.env.TZ = originalTz;
  });

  describe.each(['UTC', 'Asia/Ho_Chi_Minh', 'America/Los_Angeles'])('under TZ=%s', (tz) => {
    beforeEach(() => {
      process.env.TZ = tz;
    });

    it('formats an instant as YYYY-MM-DD HH:mm UTC', () => {
      expect(formatUtc('2030-01-07T09:00:00.000Z')).toBe('2030-01-07 09:00 UTC');
      expect(formatUtc('2030-01-07T23:59:30.123Z')).toBe('2030-01-07 23:59 UTC');
    });

    it('formats an instant given with an offset in UTC', () => {
      expect(formatUtc('2030-01-07T16:00:00+07:00')).toBe('2030-01-07 09:00 UTC');
    });

    it('reads a datetime-local value as UTC', () => {
      expect(utcInputToIso('2030-01-07T09:00')).toBe('2030-01-07T09:00:00.000Z');
      expect(utcInputToIso('2030-01-07T10:00')).toBe('2030-01-07T10:00:00.000Z');
    });

    it('turns an instant into the datetime-local value of its UTC minute', () => {
      expect(isoToUtcInput('2030-01-07T09:00:30.123Z')).toBe('2030-01-07T09:00');
      expect(isoToUtcInput('2030-01-07T16:00:00+07:00')).toBe('2030-01-07T09:00');
    });

    it('gives the epoch milliseconds of a datetime-local value read as UTC', () => {
      expect(parseUtcInput('2030-01-07T09:00')).toBe(Date.UTC(2030, 0, 7, 9, 0));
    });
  });

  it('gives NaN for a value that is not a date-time', () => {
    expect(parseUtcInput('')).toBeNaN();
    expect(parseUtcInput('nonsense')).toBeNaN();
  });
});

import { ValidationError } from 'yup';
import type { AnyObjectSchema } from 'yup';
import { END_NOT_AFTER_START_MESSAGE, createBookingSchema, editBookingSchema } from './booking-form-schema';

const editValues = { title: 'Sprint planning', startsAt: '2030-01-07T09:00', endsAt: '2030-01-07T10:00' };
const createValues = {
  ...editValues,
  roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
  organizerEmail: 'ann@example.com',
};

const errorsOf = async (schema: AnyObjectSchema, values: Record<string, string>): Promise<Record<string, string>> => {
  try {
    await schema.validate(values, { abortEarly: false });
    return {};
  } catch (error) {
    if (!(error instanceof ValidationError)) throw error;
    return Object.fromEntries(error.inner.map((issue) => [issue.path ?? '', issue.message]));
  }
};

describe.each([
  ['create', createBookingSchema, createValues],
  ['edit', editBookingSchema, editValues],
])('booking form schema, %s shape', (_, schema, valid) => {
  it('accepts valid values', async () => {
    expect(await errorsOf(schema, valid)).toEqual({});
  });

  it('rejects an end equal to the start', async () => {
    expect(await errorsOf(schema, { ...valid, endsAt: valid.startsAt })).toEqual({
      endsAt: END_NOT_AFTER_START_MESSAGE,
    });
  });

  it('rejects an end earlier than the start', async () => {
    expect(await errorsOf(schema, { ...valid, endsAt: '2030-01-07T08:59' })).toEqual({
      endsAt: END_NOT_AFTER_START_MESSAGE,
    });
  });

  it('requires title, start and end', async () => {
    const errors = await errorsOf(schema, { ...valid, title: '', startsAt: '', endsAt: '' });

    expect(errors).toMatchObject({
      title: 'Title is required',
      startsAt: 'Start is required',
      endsAt: 'End is required',
    });
  });

  it('accepts a title of 120 characters and rejects 121', async () => {
    expect(await errorsOf(schema, { ...valid, title: 'a'.repeat(120) })).toEqual({});
    expect(await errorsOf(schema, { ...valid, title: 'a'.repeat(121) })).toEqual({
      title: 'Title must be at most 120 characters',
    });
  });
});

describe('booking form schema, create-only fields', () => {
  it('requires a room and an organizer email', async () => {
    expect(await errorsOf(createBookingSchema, { ...createValues, roomId: '', organizerEmail: '' })).toEqual({
      roomId: 'Room is required',
      organizerEmail: 'Organizer email is required',
    });
  });

  it('rejects an organizer email that is not an email address', async () => {
    expect(await errorsOf(createBookingSchema, { ...createValues, organizerEmail: 'x' })).toEqual({
      organizerEmail: 'Enter a valid email address',
    });
  });
});

import { renderHook, waitFor } from '@testing-library/react';
import { ErrorCodeEnum } from '@roombook/contract';
import type { PagedRoomsDto, RoomDto } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { listRooms } from '../../services/room.service';
import { useAllRooms } from './use-all-rooms';

jest.mock('../../services/room.service', () => ({ listRooms: jest.fn() }));

const mockedListRooms = listRooms as jest.MockedFunction<typeof listRooms>;

const roomsOf = (count: number): RoomDto[] =>
  Array.from({ length: count }, (_, index) => {
    const number = String(index + 1).padStart(2, '0');
    return { id: `00000000-0000-4000-8000-0000000000${number}`, name: `Room ${number}`, capacity: 4 };
  });

const servePagesOf = (rooms: RoomDto[]) =>
  mockedListRooms.mockImplementation((page, limit) => {
    const paged: PagedRoomsDto = {
      items: rooms.slice((page - 1) * limit, page * limit),
      total: rooms.length,
      page,
      limit,
    };
    return Promise.resolve(paged);
  });

describe('useAllRooms', () => {
  beforeEach(() => mockedListRooms.mockReset());

  it('loads 12 rooms over two pages of 10 (BPG-003, R-16)', async () => {
    const rooms = roomsOf(12);
    servePagesOf(rooms);

    const { result } = renderHook(() => useAllRooms());

    await waitFor(() => expect(result.current.rooms).toHaveLength(12));
    expect(result.current.rooms).toEqual(rooms);
    expect(mockedListRooms.mock.calls).toEqual([
      [1, 10],
      [2, 10],
    ]);
    expect(result.current.error).toBeNull();
  });

  it('asks for one page only when every room fits in it', async () => {
    servePagesOf(roomsOf(10));

    const { result } = renderHook(() => useAllRooms());

    await waitFor(() => expect(result.current.rooms).toHaveLength(10));
    expect(mockedListRooms).toHaveBeenCalledTimes(1);
  });

  it('stops when a page comes back empty before the total is reached', async () => {
    mockedListRooms.mockImplementation((page, limit) =>
      Promise.resolve({ items: page === 1 ? roomsOf(10) : [], total: 25, page, limit }),
    );

    const { result } = renderHook(() => useAllRooms());

    await waitFor(() => expect(result.current.rooms).toHaveLength(10));
    expect(mockedListRooms).toHaveBeenCalledTimes(2);
  });

  it('reports the API message and offers no partial list when a page fails', async () => {
    mockedListRooms.mockImplementation((page, limit) =>
      page === 1
        ? Promise.resolve({ items: roomsOf(10), total: 12, page, limit })
        : Promise.reject(
            new ApiError({
              statusCode: 503,
              errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE,
              message: 'Room service is unavailable',
            }),
          ),
    );

    const { result } = renderHook(() => useAllRooms());

    await waitFor(() => expect(result.current.error).toBe('Room service is unavailable'));
    expect(result.current.rooms).toEqual([]);
  });
});

import { act, renderHook } from '@testing-library/react';
import { ErrorCodeEnum } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { useIdempotencyKey } from './use-idempotency-key';

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

const payload = { title: 'Sprint planning', startsAt: '2030-01-07T09:00:00.000Z' };

const apiError = (statusCode: number, errorCode: ErrorCodeEnum) =>
  new ApiError({ statusCode, errorCode, message: 'failed' });

const setup = () => renderHook(() => useIdempotencyKey()).result;

describe('useIdempotencyKey (BPG-006, R-14)', () => {
  it('issues a UUID', () => {
    expect(setup().current.keyFor(payload)).toMatch(UUID_PATTERN);
  });

  it('keeps the key for the retry of an unchanged payload after a 503', () => {
    const hook = setup();
    const first = hook.current.keyFor(payload);
    act(() => hook.current.settle(apiError(503, ErrorCodeEnum.SERVICE_UNAVAILABLE)));

    expect(hook.current.keyFor({ ...payload })).toBe(first);
  });

  it('keeps the key after a network error', () => {
    const hook = setup();
    const first = hook.current.keyFor(payload);
    act(() => hook.current.settle(new Error('Network Error')));

    expect(hook.current.keyFor(payload)).toBe(first);
  });

  it('keeps the key after a 409 in-progress answer', () => {
    const hook = setup();
    const first = hook.current.keyFor(payload);
    act(() => hook.current.settle(apiError(409, ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS)));

    expect(hook.current.keyFor(payload)).toBe(first);
  });

  it('issues a new key when the payload was edited after a 503', () => {
    const hook = setup();
    const first = hook.current.keyFor(payload);
    act(() => hook.current.settle(apiError(503, ErrorCodeEnum.SERVICE_UNAVAILABLE)));

    const second = hook.current.keyFor({ ...payload, title: 'Retro' });

    expect(second).toMatch(UUID_PATTERN);
    expect(second).not.toBe(first);
  });

  it('drops the key after a 201', () => {
    const hook = setup();
    const first = hook.current.keyFor(payload);
    act(() => hook.current.settle());

    expect(hook.current.keyFor(payload)).not.toBe(first);
  });

  it.each([
    [400, ErrorCodeEnum.VALIDATION],
    [404, ErrorCodeEnum.ROOM_NOT_FOUND],
    [422, ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED],
  ])('drops the key after a final %i answer', (statusCode, errorCode) => {
    const hook = setup();
    const first = hook.current.keyFor(payload);
    act(() => hook.current.settle(apiError(statusCode, errorCode)));

    expect(hook.current.keyFor(payload)).not.toBe(first);
  });

  it('keeps the key across re-renders', () => {
    const { result, rerender } = renderHook(() => useIdempotencyKey());
    const first = result.current.keyFor(payload);
    rerender();

    expect(result.current.keyFor(payload)).toBe(first);
  });
});

import { ApiRouteEnum, IDEMPOTENCY_KEY_HEADER } from '@roombook/contract';
import type {
  BookingDto,
  CreateBookingDto,
  ListBookingsQueryDto,
  PagedBookingsDto,
  UpdateBookingDto,
} from '@roombook/contract';
import { apiClient } from './api-client';

const BOOKINGS_PATH = `/${ApiRouteEnum.BOOKINGS}`;

export const listBookings = async (query: ListBookingsQueryDto): Promise<PagedBookingsDto> => {
  const { data } = await apiClient.get<PagedBookingsDto>(BOOKINGS_PATH, { params: query });
  return data;
};

export const createBooking = async (body: CreateBookingDto, idempotencyKey: string): Promise<BookingDto> => {
  const { data } = await apiClient.post<BookingDto>(BOOKINGS_PATH, body, {
    headers: { [IDEMPOTENCY_KEY_HEADER]: idempotencyKey },
  });
  return data;
};

export const updateBooking = async (id: string, body: UpdateBookingDto): Promise<BookingDto> => {
  const { data } = await apiClient.patch<BookingDto>(`${BOOKINGS_PATH}/${id}`, body);
  return data;
};

export const deleteBooking = async (id: string): Promise<void> => {
  await apiClient.delete(`${BOOKINGS_PATH}/${id}`);
};

const MINUTE_LENGTH = 'YYYY-MM-DDTHH:mm'.length;

export const parseUtcInput = (value: string): number => Date.parse(`${value}Z`);

export const utcInputToIso = (value: string): string => new Date(parseUtcInput(value)).toISOString();

export const isoToUtcInput = (iso: string): string => new Date(iso).toISOString().slice(0, MINUTE_LENGTH);

export const formatUtc = (iso: string): string => `${isoToUtcInput(iso).replace('T', ' ')} UTC`;

import { object, ref, string } from 'yup';
import type { InferType } from 'yup';
import { BOOKING_TITLE_MAX_LENGTH } from '@roombook/contract';
import { parseUtcInput } from './utc-date-time';

export const END_NOT_AFTER_START_MESSAGE = 'End must be later than start';

const startsAtRef = ref<string>('startsAt');

export const editBookingSchema = object({
  title: string()
    .required('Title is required')
    .max(BOOKING_TITLE_MAX_LENGTH, `Title must be at most ${BOOKING_TITLE_MAX_LENGTH} characters`),
  startsAt: string().required('Start is required'),
  endsAt: string()
    .required('End is required')
    .test('later-than-start', END_NOT_AFTER_START_MESSAGE, (endsAt, context) => {
      const startsAt = context.resolve(startsAtRef);
      return !endsAt || !startsAt || parseUtcInput(endsAt) > parseUtcInput(startsAt);
    }),
});

export const createBookingSchema = editBookingSchema.concat(
  object({
    roomId: string().required('Room is required'),
    organizerEmail: string().required('Organizer email is required').email('Enter a valid email address'),
  }),
);

export type EditBookingFormValues = InferType<typeof editBookingSchema>;
export type CreateBookingFormValues = InferType<typeof createBookingSchema>;

import { useEffect, useState } from 'react';
import { DEFAULT_PAGE_SIZE } from '@roombook/contract';
import type { RoomDto } from '@roombook/contract';
import { listRooms } from '../../services/room.service';
import { errorMessage } from './error-message';

const loadEveryRoom = async (): Promise<RoomDto[]> => {
  const rooms: RoomDto[] = [];
  for (let page = 1; ; page += 1) {
    const { items, total } = await listRooms(page, DEFAULT_PAGE_SIZE);
    rooms.push(...items);
    if (items.length === 0 || rooms.length >= total) return rooms;
  }
};

export function useAllRooms() {
  const [rooms, setRooms] = useState<RoomDto[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    loadEveryRoom()
      .then((loaded) => active && setRooms(loaded))
      .catch((e: unknown) => active && setError(errorMessage(e)));
    return () => {
      active = false;
    };
  }, []);

  return { rooms, error };
}

import { useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { ErrorCodeEnum } from '@roombook/contract';
import { ApiError } from '../../services/api-error';

type IssuedKey = {
  key: string;
  payload: string;
};

const FIRST_SERVER_ERROR_STATUS = 500;

const isFinalAnswer = (error: unknown): boolean =>
  error instanceof ApiError &&
  error.statusCode < FIRST_SERVER_ERROR_STATUS &&
  error.errorCode !== ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS;

export function useIdempotencyKey() {
  const issued = useRef<IssuedKey | null>(null);

  const keyFor = useCallback((payload: object): string => {
    const serialized = JSON.stringify(payload);
    if (issued.current?.payload !== serialized) issued.current = { key: uuidv4(), payload: serialized };
    return issued.current.key;
  }, []);

  const settle = useCallback((error?: unknown): void => {
    if (error === undefined || isFinalAnswer(error)) issued.current = null;
  }, []);

  return { keyFor, settle };
}

import { ConfirmationStatusEnum } from '@roombook/contract';
import type { BookingDto, PagedBookingsDto, PagedRoomsDto, RoomDto } from '@roombook/contract';

export const ATLAS_ID = '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10';

export const atlas: RoomDto = { id: ATLAS_ID, name: 'Atlas', capacity: 8 };

export const twelveRooms: RoomDto[] = [
  atlas,
  ...Array.from({ length: 11 }, (_, index) => {
    const number = String(index + 2).padStart(2, '0');
    return { id: `00000000-0000-4000-8000-0000000000${number}`, name: `Room ${number}`, capacity: 4 };
  }),
];

export const bookingOf = (overrides: Partial<BookingDto> = {}): BookingDto => ({
  id: '7a1d2c3b-0000-4000-8000-000000000001',
  roomId: ATLAS_ID,
  title: 'Sprint planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
  ...overrides,
});

export const bookingsOf = (count: number): BookingDto[] =>
