import { BookingEntity, ExceptionHelper } from '@roombook/backend-common';
import { CreateBookingDto, ErrorCodeEnum, UpdateBookingDto } from '@roombook/contract';
import { INSTANT_GRAMMAR, parseInstant } from './booking-instant';

export class NormalisedBookingDto {
  roomId: string;
  title: string;
  organizerEmail: string;
  startsAt: Date;
  endsAt: Date;
}

export class BookingChangesDto {
  title?: string;
  startsAt?: Date;
  endsAt?: Date;
}

const requireInstant = (field: string, value: unknown): Date =>
  parseInstant(value) ??
  ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, `${field} must be an instant in the form ${INSTANT_GRAMMAR}`);

export const rejectInvalidSpan = (): never =>
  ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'endsAt must be later than startsAt');

const requireSpan = (startsAt: Date, endsAt: Date): void => {
  if (endsAt.getTime() <= startsAt.getTime()) {
    rejectInvalidSpan();
  }
};

export const normaliseCreateBooking = (body: CreateBookingDto): NormalisedBookingDto => {
  const startsAt = requireInstant('startsAt', body.startsAt);
  const endsAt = requireInstant('endsAt', body.endsAt);
  requireSpan(startsAt, endsAt);
  return {
    roomId: body.roomId.toLowerCase(),
    title: body.title,
    organizerEmail: body.organizerEmail,
    startsAt,
    endsAt,
  };
};

export const parseBookingChanges = (changes: UpdateBookingDto): BookingChangesDto => {
  const parsed = new BookingChangesDto();
  if (changes.title !== undefined) {
    if (typeof changes.title !== 'string') {
      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'title must be a string');
    }
    parsed.title = changes.title;
  }
  if (changes.startsAt !== undefined) {
    parsed.startsAt = requireInstant('startsAt', changes.startsAt);
  }
  if (changes.endsAt !== undefined) {
    parsed.endsAt = requireInstant('endsAt', changes.endsAt);
  }
  return parsed;
};

export const mergeBookingChanges = (stored: BookingEntity, changes: BookingChangesDto): BookingChangesDto => {
  const startsAt = changes.startsAt ?? stored.startsAt;
  const endsAt = changes.endsAt ?? stored.endsAt;
  requireSpan(startsAt, endsAt);
  const changed = new BookingChangesDto();
  if (changes.title !== undefined && changes.title !== stored.title) {
    changed.title = changes.title;
  }
  if (startsAt.getTime() !== stored.startsAt.getTime()) {
    changed.startsAt = startsAt;
  }
  if (endsAt.getTime() !== stored.endsAt.getTime()) {
    changed.endsAt = endsAt;
  }
  return changed;
};

import { ReactNode, useId } from 'react';
import { useFormContext } from 'react-hook-form';
import TextField from '@mui/material/TextField';
import type { CreateBookingFormValues } from './booking-form-schema';

type BookingFieldName = keyof CreateBookingFormValues;

type BookingFormFieldProps = {
  name: BookingFieldName;
  label: string;
  type?: string;
  revalidates?: BookingFieldName;
  children?: ReactNode;
};

export function BookingFormField({ name, label, type, revalidates, children }: BookingFormFieldProps) {
  const id = useId();
  const { register, formState } = useFormContext<CreateBookingFormValues>();
  const { ref, ...field } = register(name, { deps: revalidates });
  const error = formState.errors[name];

  return (
    <TextField
      id={id}
      label={label}
      type={type}
      select={Boolean(children)}
      SelectProps={{ native: true }}
      InputLabelProps={{ shrink: true }}
      inputRef={ref}
      error={Boolean(error)}
      helperText={error?.message}
      size="small"
      fullWidth
      {...field}
    >
      {children}
    </TextField>
  );
}

export function BookingScheduleFields() {
  return (
    <>
      <BookingFormField name="title" label="Title" />
      <BookingFormField name="startsAt" label="Start (UTC)" type="datetime-local" revalidates="endsAt" />
      <BookingFormField name="endsAt" label="End (UTC)" type="datetime-local" />
    </>
  );
}

import { createHash } from 'crypto';
import { NormalisedBookingDto } from './booking-input';

export const bookingFingerprint = (booking: NormalisedBookingDto): string =>
  createHash('sha256')
    .update(
      JSON.stringify([
        booking.roomId,
        booking.title,
        booking.organizerEmail,
        booking.startsAt.getTime(),
        booking.endsAt.getTime(),
      ]),
    )
    .digest('hex');

import { useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import Alert from '@mui/material/Alert';
import Button from '@mui/material/Button';
import Paper from '@mui/material/Paper';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import type { CreateBookingDto, RoomDto } from '@roombook/contract';
import { createBooking } from '../../services/booking.service';
import { BookingFormField, BookingScheduleFields } from './booking-form-fields';
import { createBookingSchema } from './booking-form-schema';
import type { CreateBookingFormValues } from './booking-form-schema';
import { errorMessage } from './error-message';
import { useIdempotencyKey } from './use-idempotency-key';
import { utcInputToIso } from './utc-date-time';

const EMPTY_VALUES: CreateBookingFormValues = { roomId: '', organizerEmail: '', title: '', startsAt: '', endsAt: '' };

type CreateBookingFormProps = {
  rooms: RoomDto[];
  onCreated: () => void;
};

export function CreateBookingForm({ rooms, onCreated }: CreateBookingFormProps) {
  const form = useForm<CreateBookingFormValues>({
    defaultValues: EMPTY_VALUES,
    resolver: yupResolver(createBookingSchema),
  });
  const { keyFor, settle } = useIdempotencyKey();
  const [submitError, setSubmitError] = useState<string | null>(null);

  const submit = async (values: CreateBookingFormValues) => {
    const body: CreateBookingDto = {
      roomId: values.roomId,
      title: values.title,
      organizerEmail: values.organizerEmail,
      startsAt: utcInputToIso(values.startsAt),
      endsAt: utcInputToIso(values.endsAt),
    };
    setSubmitError(null);
    try {
      await createBooking(body, keyFor(body));
    } catch (error) {
      settle(error);
      setSubmitError(errorMessage(error));
      return;
    }
    settle();
    form.reset();
    onCreated();
  };

  return (
    <FormProvider {...form}>
      <Paper
        component="form"
        aria-label="New booking"
        noValidate
        onSubmit={form.handleSubmit(submit)}
        sx={{ p: 2, mb: 3 }}
      >
        <Stack spacing={2}>
          <Typography variant="h6" component="h2">
            New booking
          </Typography>
          {submitError && <Alert severity="error">{submitError}</Alert>}
          <BookingFormField name="roomId" label="Room">
            <option value="">Select a room</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>
                {room.name}
              </option>
            ))}
          </BookingFormField>
          <BookingFormField name="organizerEmail" label="Organizer email" type="email" />
          <BookingScheduleFields />
          <Button type="submit" variant="contained" disabled={form.formState.isSubmitting} sx={{ alignSelf: 'flex-start' }}>
            Create booking
          </Button>
        </Stack>
      </Paper>
    </FormProvider>
  );
}

import { useId, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import Alert from '@mui/material/Alert';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Stack from '@mui/material/Stack';
import type { BookingDto, UpdateBookingDto } from '@roombook/contract';
import { updateBooking } from '../../services/booking.service';
import { BookingScheduleFields } from './booking-form-fields';
import { editBookingSchema } from './booking-form-schema';
import type { EditBookingFormValues } from './booking-form-schema';
import { errorMessage } from './error-message';
import { isoToUtcInput, utcInputToIso } from './utc-date-time';

const toFormValues = (booking: BookingDto): EditBookingFormValues => ({
  title: booking.title,
  startsAt: isoToUtcInput(booking.startsAt),
  endsAt: isoToUtcInput(booking.endsAt),
});

const changedFields = (shown: EditBookingFormValues, entered: EditBookingFormValues): UpdateBookingDto => ({
  ...(entered.title !== shown.title && { title: entered.title }),
  ...(entered.startsAt !== shown.startsAt && { startsAt: utcInputToIso(entered.startsAt) }),
  ...(entered.endsAt !== shown.endsAt && { endsAt: utcInputToIso(entered.endsAt) }),
});

type EditBookingDialogProps = {
  booking: BookingDto;
  onClose: () => void;
  onSaved: () => void;
};

export function EditBookingDialog({ booking, onClose, onSaved }: EditBookingDialogProps) {
  const titleId = useId();
  const shown = toFormValues(booking);
  const form = useForm<EditBookingFormValues>({ defaultValues: shown, resolver: yupResolver(editBookingSchema) });
  const [saveError, setSaveError] = useState<string | null>(null);

  const save = async (entered: EditBookingFormValues) => {
    const changes = changedFields(shown, entered);
    if (Object.keys(changes).length === 0) {
      onClose();
      return;
    }
    setSaveError(null);
    try {
      await updateBooking(booking.id, changes);
    } catch (error) {
      setSaveError(errorMessage(error));
      return;
    }
    onSaved();
  };

  return (
    <Dialog open onClose={onClose} aria-labelledby={titleId} fullWidth maxWidth="xs">
      <FormProvider {...form}>
        <form noValidate onSubmit={form.handleSubmit(save)}>
          <DialogTitle id={titleId}>Edit booking</DialogTitle>
          <DialogContent>
            <Stack spacing={2} sx={{ pt: 1 }}>
              {saveError && <Alert severity="error">{saveError}</Alert>}
              <BookingScheduleFields />
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button onClick={onClose}>Cancel</Button>
            <Button type="submit" variant="contained" disabled={form.formState.isSubmitting}>
              Save
            </Button>
          </DialogActions>
        </form>
      </FormProvider>
    </Dialog>
  );
}

import Button from '@mui/material/Button';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import type { BookingDto, RoomDto } from '@roombook/contract';
import { formatUtc } from './utc-date-time';

const COLUMNS = ['Title', 'Room', 'Organizer', 'Start (UTC)', 'End (UTC)', 'Confirmation', 'Actions'];

type BookingsTableProps = {
  bookings: BookingDto[];
  rooms: RoomDto[];
  busy: boolean;
  onEdit: (booking: BookingDto) => void;
  onDelete: (booking: BookingDto) => void;
};

export function BookingsTable({ bookings, rooms, busy, onEdit, onDelete }: BookingsTableProps) {
  const roomNames = new Map(rooms.map((room) => [room.id, room.name]));

  return (
    <TableContainer>
      <Table aria-label="Bookings">
        <TableHead>
          <TableRow>
            {COLUMNS.map((column) => (
              <TableCell key={column}>{column}</TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {bookings.length === 0 ? (
            <TableRow>
              <TableCell colSpan={COLUMNS.length} align="center">
                No bookings yet
              </TableCell>
            </TableRow>
          ) : (
            bookings.map((booking) => (
              <TableRow key={booking.id}>
                <TableCell>{booking.title}</TableCell>
                <TableCell>{roomNames.get(booking.roomId) ?? booking.roomId}</TableCell>
                <TableCell>{booking.organizerEmail}</TableCell>
                <TableCell>{formatUtc(booking.startsAt)}</TableCell>
                <TableCell>{formatUtc(booking.endsAt)}</TableCell>
                <TableCell>{booking.confirmationStatus}</TableCell>
                <TableCell sx={{ whiteSpace: 'nowrap' }}>
                  <Button size="small" disabled={busy} aria-label={`Edit ${booking.title}`} onClick={() => onEdit(booking)}>
                    Edit
                  </Button>
                  <Button
                    size="small"
                    color="error"
                    disabled={busy}
                    aria-label={`Delete ${booking.title}`}
                    onClick={() => onDelete(booking)}
                  >
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

import TextField from '@mui/material/TextField';
import type { RoomDto } from '@roombook/contract';

type RoomFilterProps = {
