  const bookings = { findAndCount: jest.fn(), findOneBy: jest.fn(), delete: jest.fn(), update: jest.fn() };
  const manager = { findOne: jest.fn(), update: jest.fn(), findOneByOrFail: jest.fn() };
  const transaction = jest.fn();

  beforeEach(async () => {
    jest.resetAllMocks();
    transaction.mockImplementation((work: (transactionManager: typeof manager) => unknown) => work(manager));
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingRepository,
        { provide: getRepositoryToken(BookingEntity), useValue: bookings },
        { provide: DataSource, useValue: { transaction } },
      ],
    }).compile();
    repository = moduleRef.get(BookingRepository);
  });

  describe('findPage (BKG-006)', () => {
    it('orders by start then id and skips (page - 1) * limit rows', async () => {
      bookings.findAndCount.mockResolvedValue([[entity()], 3]);

      const page = await repository.findPage({ page: 2, limit: 2 });

      expect(bookings.findAndCount).toHaveBeenCalledWith({
        where: {},
        order: { startsAt: 'ASC', id: 'ASC' },
        skip: 2,
        take: 2,
      });
      expect(page).toEqual({ items: [dto()], total: 3, page: 2, limit: 2 });
    });

    it('uses the requested limit, not the default page size, for the offset', async () => {
      bookings.findAndCount.mockResolvedValue([[], 0]);

      await repository.findPage({ page: 3, limit: 25 });

      expect(bookings.findAndCount).toHaveBeenCalledWith(expect.objectContaining({ skip: 50, take: 25 }));
    });

    it('filters by room when a room id is given', async () => {
      bookings.findAndCount.mockResolvedValue([[], 0]);

      await repository.findPage({ page: 1, limit: 10, roomId: ROOM_ID });

      expect(bookings.findAndCount).toHaveBeenCalledWith(expect.objectContaining({ where: { roomId: ROOM_ID } }));
    });

    it('answers an empty page past the end with the real total', async () => {
      bookings.findAndCount.mockResolvedValue([[], 3]);

      await expect(repository.findPage({ page: 9, limit: 10 })).resolves.toEqual({
        items: [],
        total: 3,
        page: 9,
        limit: 10,
      });
    });
  });

  describe('findById (BKG-007)', () => {
    it('maps the row to a booking with UTC millisecond instants', async () => {
      bookings.findOneBy.mockResolvedValue(entity({ startsAt: new Date('2030-01-07T16:00:00+07:00') }));

      await expect(repository.findById(ID)).resolves.toEqual(dto());
      expect(bookings.findOneBy).toHaveBeenCalledWith({ id: ID });
    });

    it('returns null for an unknown booking', async () => {
      bookings.findOneBy.mockResolvedValue(null);

      await expect(repository.findById(ID)).resolves.toBeNull();
    });
  });

  describe('deleteById (BKG-010)', () => {
    it('reports whether a row was removed', async () => {
      bookings.delete.mockResolvedValueOnce({ affected: 1 }).mockResolvedValueOnce({ affected: 0 });

      await expect(repository.deleteById(ID)).resolves.toBe(true);
      await expect(repository.deleteById(ID)).resolves.toBe(false);
      expect(bookings.delete).toHaveBeenCalledWith({ id: ID });
    });
  });

  describe('update (BKG-008, BKG-009)', () => {
    it('locks the row, writes only the changed column and answers the stored result', async () => {
      const updatedAt = new Date('2030-01-02T00:00:00.000Z');
      manager.findOne.mockResolvedValue(entity());
      manager.findOneByOrFail.mockResolvedValue(entity({ title: 'Retro', updatedAt }));

      const result = await repository.update(ID, { title: 'Retro' });

      expect(transaction).toHaveBeenCalledTimes(1);
      expect(manager.findOne).toHaveBeenCalledWith(BookingEntity, {
        where: { id: ID },
        lock: { mode: 'pessimistic_write' },
      });
      expect(manager.update).toHaveBeenCalledWith(BookingEntity, { id: ID }, { title: 'Retro' });
      expect(result).toEqual(dto({ title: 'Retro', updatedAt: '2030-01-02T00:00:00.000Z' }));
    });

    it('writes nothing and answers the booking when no value changes', async () => {
      manager.findOne.mockResolvedValue(entity());

      await expect(repository.update(ID, {})).resolves.toEqual(dto());
      await expect(repository.update(ID, { title: 'Sprint planning' })).resolves.toEqual(dto());
      expect(manager.update).not.toHaveBeenCalled();
    });

    it('returns null for an unknown booking without writing', async () => {
      manager.findOne.mockResolvedValue(null);

      await expect(repository.update(ID, { title: 'Retro' })).resolves.toBeNull();
      expect(manager.update).not.toHaveBeenCalled();
    });

    it('rejects a start that reaches the stored end with 400 and writes nothing (BKG-004)', async () => {
      manager.findOne.mockResolvedValue(entity());

      const error = await repository
        .update(ID, { startsAt: new Date('2030-01-07T10:00:00.000Z') })
        .catch((caught: unknown) => caught);

      expect((error as RpcException).getError()).toEqual(
        expect.objectContaining({ statusCode: 400, errorCode: ErrorCodeEnum.VALIDATION }),
      );
      expect(manager.update).not.toHaveBeenCalled();
    });

    it('maps a CHK_bookings_span violation to the same 400 (BKG-011)', async () => {
      manager.findOne.mockResolvedValue(entity());
      manager.update.mockRejectedValue(spanViolation());

      const error = await repository
        .update(ID, { endsAt: new Date('2030-01-07T11:00:00.000Z') })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(RpcException);
      expect((error as RpcException).getError()).toEqual({
        statusCode: 400,
        errorCode: ErrorCodeEnum.VALIDATION,
        message: 'endsAt must be later than startsAt',
      });
    });

    it('passes any other database error through', async () => {
      const failure = new QueryFailedError('UPDATE', [], new Error('connection lost'));
      manager.findOne.mockResolvedValue(entity());
      manager.update.mockRejectedValue(failure);

      await expect(repository.update(ID, { title: 'Retro' })).rejects.toBe(failure);
    });
  });

  describe('recordConfirmation (CNF-006)', () => {
    it('updates only a booking that is not SENT and has no higher attempt count', async () => {
      bookings.update.mockResolvedValue({ affected: 1 });
      bookings.findOneBy.mockResolvedValue(
        entity({ confirmationStatus: ConfirmationStatusEnum.SENT, confirmationAttempts: 3 }),
      );

      const result = await repository.recordConfirmation({
        bookingId: ID,
        status: ConfirmationStatusEnum.SENT,
        attempts: 3,
      });

      expect(bookings.update).toHaveBeenCalledTimes(1);
      expect(bookings.update).toHaveBeenCalledWith(
        {
          id: ID,
          confirmationStatus: Not(ConfirmationStatusEnum.SENT),
          confirmationAttempts: LessThanOrEqual(3),
        },
        { confirmationStatus: ConfirmationStatusEnum.SENT, confirmationAttempts: 3 },
      );
      expect(result).toEqual(dto({ confirmationStatus: ConfirmationStatusEnum.SENT, confirmationAttempts: 3 }));
    });

    it('answers the stored booking when the result was late', async () => {
      bookings.update.mockResolvedValue({ affected: 0 });
      bookings.findOneBy.mockResolvedValue(
        entity({ confirmationStatus: ConfirmationStatusEnum.SENT, confirmationAttempts: 1 }),
      );

      await expect(
        repository.recordConfirmation({ bookingId: ID, status: ConfirmationStatusEnum.PENDING, attempts: 1 }),
      ).resolves.toEqual(dto({ confirmationStatus: ConfirmationStatusEnum.SENT, confirmationAttempts: 1 }));
    });

    it('returns null for an unknown booking', async () => {
      bookings.update.mockResolvedValue({ affected: 0 });
      bookings.findOneBy.mockResolvedValue(null);

      await expect(
        repository.recordConfirmation({ bookingId: ID, status: ConfirmationStatusEnum.SENT, attempts: 1 }),
      ).resolves.toBeNull();
    });
  });
});

