import { getRepositoryToken } from '@nestjs/typeorm';
import { BookingEntity } from '@roombook/backend-common';
import { BookingDto, ConfirmationStatusEnum } from '@roombook/contract';
import { DataSource } from 'typeorm';
import { BookingRepository } from './booking.repository';

const ID = '9d0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a99';
const ROOM_ID = '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10';

const entity = (overrides: Partial<BookingEntity> = {}): BookingEntity =>
  Object.assign(new BookingEntity(), {
    id: ID,
    roomId: ROOM_ID,
    title: 'Sprint planning',
    organizerEmail: 'ann@example.com',
    startsAt: new Date('2030-01-07T09:00:00.000Z'),
    endsAt: new Date('2030-01-07T10:00:00.000Z'),
    confirmationStatus: ConfirmationStatusEnum.PENDING,
    confirmationAttempts: 0,
    createdAt: new Date('2030-01-01T00:00:00.000Z'),
    updatedAt: new Date('2030-01-01T00:00:00.000Z'),
    ...overrides,
  });

const dto: BookingDto = {
  id: ID,
  roomId: ROOM_ID,
  title: 'Sprint planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

describe('BookingRepository reads and delete', () => {
  let repository: BookingRepository;
  const bookings = { findAndCount: jest.fn(), findOneBy: jest.fn(), delete: jest.fn() };

  beforeEach(async () => {
    jest.resetAllMocks();
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingRepository,
        { provide: getRepositoryToken(BookingEntity), useValue: bookings },
        { provide: DataSource, useValue: {} },
      ],
    }).compile();
    repository = moduleRef.get(BookingRepository);
  });

  describe('findPage (BKG-006)', () => {
    it('orders by start then id and skips (page - 1) * limit rows', async () => {
      bookings.findAndCount.mockResolvedValue([[entity()], 3]);

      const page = await repository.findPage({ page: 2, limit: 2 });

      expect(bookings.findAndCount).toHaveBeenCalledWith({
        where: {},
        order: { startsAt: 'ASC', id: 'ASC' },
        skip: 2,
        take: 2,
      });
      expect(page).toEqual({ items: [dto], total: 3, page: 2, limit: 2 });
    });

    it('uses the requested limit, not the default page size, for the offset', async () => {
      bookings.findAndCount.mockResolvedValue([[], 0]);

      await repository.findPage({ page: 3, limit: 25 });

      expect(bookings.findAndCount).toHaveBeenCalledWith(expect.objectContaining({ skip: 50, take: 25 }));
    });

    it('filters by room when a room id is given', async () => {
      bookings.findAndCount.mockResolvedValue([[], 0]);

      await repository.findPage({ page: 1, limit: 10, roomId: ROOM_ID });

      expect(bookings.findAndCount).toHaveBeenCalledWith(expect.objectContaining({ where: { roomId: ROOM_ID } }));
    });

    it('answers an empty page past the end with the real total', async () => {
      bookings.findAndCount.mockResolvedValue([[], 3]);

      await expect(repository.findPage({ page: 9, limit: 10 })).resolves.toEqual({
        items: [],
        total: 3,
        page: 9,
        limit: 10,
      });
    });
  });

  describe('findById (BKG-007)', () => {
    it('maps the row to a booking with UTC millisecond instants', async () => {
      bookings.findOneBy.mockResolvedValue(entity({ startsAt: new Date('2030-01-07T16:00:00+07:00') }));

      await expect(repository.findById(ID)).resolves.toEqual(dto);
      expect(bookings.findOneBy).toHaveBeenCalledWith({ id: ID });
    });

    it('returns null for an unknown booking', async () => {
      bookings.findOneBy.mockResolvedValue(null);

      await expect(repository.findById(ID)).resolves.toBeNull();
    });
  });

  describe('deleteById (BKG-010)', () => {
    it('reports whether a row was removed', async () => {
      bookings.delete.mockResolvedValueOnce({ affected: 1 }).mockResolvedValueOnce({ affected: 0 });

      await expect(repository.deleteById(ID)).resolves.toBe(true);
      await expect(repository.deleteById(ID)).resolves.toBe(false);
      expect(bookings.delete).toHaveBeenCalledWith({ id: ID });
    });
  });
});

import { RpcException } from '@nestjs/microservices';
import { Test } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { BookingEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum, ErrorCodeEnum } from '@roombook/contract';
import { DataSource, LessThanOrEqual, Not, QueryFailedError } from 'typeorm';
import { BookingRepository } from './booking.repository';

const ID = '9d0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a99';
const { PENDING, SENT } = ConfirmationStatusEnum;

const entity = (overrides: Partial<BookingEntity> = {}): BookingEntity =>
  Object.assign(new BookingEntity(), {
    id: ID,
    roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
    title: 'Sprint planning',
    organizerEmail: 'ann@example.com',
    startsAt: new Date('2030-01-07T09:00:00.000Z'),
    endsAt: new Date('2030-01-07T10:00:00.000Z'),
    confirmationStatus: PENDING,
    confirmationAttempts: 0,
    createdAt: new Date('2030-01-01T00:00:00.000Z'),
    updatedAt: new Date('2030-01-01T00:00:00.000Z'),
    ...overrides,
  });

const spanViolation = (): QueryFailedError =>
  new QueryFailedError('UPDATE', [], Object.assign(new Error('violates check'), { constraint: 'CHK_bookings_span' }));

describe('BookingRepository writes', () => {
  let repository: BookingRepository;
  const bookings = { findOneBy: jest.fn(), update: jest.fn() };
  const manager = { findOne: jest.fn(), update: jest.fn(), findOneByOrFail: jest.fn() };
  const transaction = jest.fn();

  beforeEach(async () => {
    jest.resetAllMocks();
    transaction.mockImplementation((work: (transactionManager: typeof manager) => unknown) => work(manager));
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingRepository,
        { provide: getRepositoryToken(BookingEntity), useValue: bookings },
        { provide: DataSource, useValue: { transaction } },
      ],
    }).compile();
    repository = moduleRef.get(BookingRepository);
  });

  describe('update (BKG-008, BKG-009)', () => {
    it('locks the row, writes only the changed column and answers the stored result', async () => {
      manager.findOne.mockResolvedValue(entity());
      manager.findOneByOrFail.mockResolvedValue(
        entity({ title: 'Retro', updatedAt: new Date('2030-01-02T00:00:00.000Z') }),
      );

      const result = await repository.update(ID, { title: 'Retro' });

      expect(transaction).toHaveBeenCalledTimes(1);
      expect(manager.findOne).toHaveBeenCalledWith(BookingEntity, {
        where: { id: ID },
        lock: { mode: 'pessimistic_write' },
      });
      expect(manager.update).toHaveBeenCalledWith(BookingEntity, { id: ID }, { title: 'Retro' });
      expect(result).toMatchObject({
        title: 'Retro',
        endsAt: '2030-01-07T10:00:00.000Z',
        updatedAt: '2030-01-02T00:00:00.000Z',
      });
    });

    it('writes nothing and answers the booking when no value changes', async () => {
      manager.findOne.mockResolvedValue(entity());

      await expect(repository.update(ID, {})).resolves.toMatchObject({ id: ID, title: 'Sprint planning' });
      await expect(repository.update(ID, { title: 'Sprint planning' })).resolves.toMatchObject({
        updatedAt: '2030-01-01T00:00:00.000Z',
      });
      expect(manager.update).not.toHaveBeenCalled();
    });

    it('returns null for an unknown booking without writing', async () => {
      manager.findOne.mockResolvedValue(null);

      await expect(repository.update(ID, { title: 'Retro' })).resolves.toBeNull();
      expect(manager.update).not.toHaveBeenCalled();
    });

    it('rejects a start that reaches the stored end with 400 and writes nothing (BKG-004)', async () => {
      manager.findOne.mockResolvedValue(entity());

      const error = await repository
        .update(ID, { startsAt: new Date('2030-01-07T10:00:00.000Z') })
        .catch((caught: unknown) => caught);

      expect((error as RpcException).getError()).toEqual(
        expect.objectContaining({ statusCode: 400, errorCode: ErrorCodeEnum.VALIDATION }),
      );
      expect(manager.update).not.toHaveBeenCalled();
    });

    it('maps a CHK_bookings_span violation to the same 400 (BKG-011)', async () => {
      manager.findOne.mockResolvedValue(entity());
      manager.update.mockRejectedValue(spanViolation());

      const error = await repository
        .update(ID, { endsAt: new Date('2030-01-07T11:00:00.000Z') })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(RpcException);
      expect((error as RpcException).getError()).toEqual({
        statusCode: 400,
        errorCode: ErrorCodeEnum.VALIDATION,
        message: 'endsAt must be later than startsAt',
      });
    });

    it('passes any other database error through', async () => {
      const failure = new QueryFailedError('UPDATE', [], new Error('connection lost'));
      manager.findOne.mockResolvedValue(entity());
      manager.update.mockRejectedValue(failure);

      await expect(repository.update(ID, { title: 'Retro' })).rejects.toBe(failure);
    });
  });

  describe('recordConfirmation (CNF-006)', () => {
    it('updates only a booking that is not SENT and has no higher attempt count', async () => {
      bookings.findOneBy.mockResolvedValue(entity({ confirmationStatus: SENT, confirmationAttempts: 3 }));

      const result = await repository.recordConfirmation({ bookingId: ID, status: SENT, attempts: 3 });

      expect(bookings.update).toHaveBeenCalledTimes(1);
      expect(bookings.update).toHaveBeenCalledWith(
        { id: ID, confirmationStatus: Not(SENT), confirmationAttempts: LessThanOrEqual(3) },
        { confirmationStatus: SENT, confirmationAttempts: 3 },
      );
      expect(result).toMatchObject({ id: ID, confirmationStatus: SENT, confirmationAttempts: 3 });
    });

    it('answers the stored booking when the result was late', async () => {
      bookings.findOneBy.mockResolvedValue(entity({ confirmationStatus: SENT, confirmationAttempts: 1 }));

      await expect(
        repository.recordConfirmation({ bookingId: ID, status: PENDING, attempts: 1 }),
      ).resolves.toMatchObject({ confirmationStatus: SENT, confirmationAttempts: 1 });
    });

    it('returns null for an unknown booking', async () => {
      bookings.findOneBy.mockResolvedValue(null);

      await expect(repository.recordConfirmation({ bookingId: ID, status: SENT, attempts: 1 })).resolves.toBeNull();
    });
  });
});

import { RpcException } from '@nestjs/microservices';
import { EmptyResponseException } from '@nestjs/microservices/errors/empty-response.exception';
import { Test } from '@nestjs/testing';
import { NATS_CLIENT } from '@roombook/backend-common';
import {
  BookingDto,
  ConfirmationStatusEnum,
  CreateBookingDto,
  ErrorCodeEnum,
  RoomPatternEnum,
} from '@roombook/contract';
import { of, throwError } from 'rxjs';
import { bookingFingerprint } from './booking-fingerprint';
import { normaliseCreateBooking } from './booking-input';
import { BookingRepository } from './booking.repository';
import { BookingService } from './booking.service';
import { ConfirmationProducer } from './confirmation.producer';
import { IdempotentBookingRepository } from './idempotent-booking.repository';

const R1 = '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10';
const K1 = '11111111-1111-4111-8111-111111111111';
const ID = '9d0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a99';

const B1: CreateBookingDto = {
  roomId: R1,
  title: 'Sprint planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
};

const booking: BookingDto = {
  ...B1,
  id: ID,
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

const errorOf = (promise: Promise<unknown>): Promise<unknown> =>
  promise.then(
    () => undefined,
    (error: unknown) => error,
  );

const expectRpcError = (error: unknown, statusCode: number, errorCode: ErrorCodeEnum): void => {
  expect(error).toBeInstanceOf(RpcException);
  expect((error as RpcException).getError()).toEqual(expect.objectContaining({ statusCode, errorCode }));
};

describe('BookingService.createBooking', () => {
  let service: BookingService;
  const send = jest.fn();
  const enqueue = jest.fn();
  const create = jest.fn();

  const createB1 = (changes: Partial<CreateBookingDto> = {}): Promise<unknown> =>
    service.createBooking({ idempotencyKey: K1, booking: { ...B1, ...changes } });

  const expectNothingStored = (): void => {
    expect(create).not.toHaveBeenCalled();
    expect(enqueue).not.toHaveBeenCalled();
  };

  beforeEach(async () => {
    jest.resetAllMocks();
    send.mockReturnValue(of({ id: R1, name: 'Atlas', capacity: 4 }));
    create.mockResolvedValue({ kind: 'created', booking });
    enqueue.mockResolvedValue(undefined);
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingService,
        { provide: BookingRepository, useValue: {} },
        { provide: IdempotentBookingRepository, useValue: { create } },
        { provide: ConfirmationProducer, useValue: { enqueue } },
        { provide: NATS_CLIENT, useValue: { send } },
      ],
    }).compile();
    service = moduleRef.get(BookingService);
  });

  it('asks the room service, stores, then enqueues, and answers the new booking (BKG-001, BKG-005)', async () => {
    await expect(createB1()).resolves.toEqual({ booking, replayed: false });

    expect(send).toHaveBeenCalledWith(RoomPatternEnum.FIND_BY_ID, { id: R1 });
    expect(create).toHaveBeenCalledWith({
      key: K1,
      fingerprint: bookingFingerprint(normaliseCreateBooking(B1)),
      booking: normaliseCreateBooking(B1),
    });
    expect(enqueue).toHaveBeenCalledWith(ID);
    expect(send.mock.invocationCallOrder[0]).toBeLessThan(create.mock.invocationCallOrder[0]);
    expect(create.mock.invocationCallOrder[0]).toBeLessThan(enqueue.mock.invocationCallOrder[0]);
  });

  it('stores the offset form as its UTC instant with the fingerprint of the same request (BKG-001)', async () => {
    await createB1({ startsAt: '2030-01-07T16:00:00+07:00' });

    expect(create.mock.calls[0][0].booking.startsAt.toISOString()).toBe('2030-01-07T09:00:00.000Z');
    expect(create.mock.calls[0][0].fingerprint).toBe(bookingFingerprint(normaliseCreateBooking(B1)));
  });

  it.each([
    ['an end equal to the start', { endsAt: B1.startsAt }],
    ['an instant without an offset', { startsAt: '2030-01-07T09:00:00' }],
  ])('answers 400 for %s before asking the room service and stores nothing (IDM-007)', async (_case, changes) => {
    expectRpcError(await errorOf(createB1(changes)), 400, ErrorCodeEnum.VALIDATION);

    expect(send).not.toHaveBeenCalled();
    expectNothingStored();
  });

  it('answers 404 NOT_FOUND.ROOM for an unknown room and stores nothing (BKG-005, IDM-007)', async () => {
    const notFound = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: `Room ${R1} was not found` };
    send.mockReturnValue(throwError(() => notFound));

    const error = await errorOf(createB1());

    expectRpcError(error, 404, ErrorCodeEnum.ROOM_NOT_FOUND);
    expect((error as RpcException).getError()).toEqual(notFound);
    expectNothingStored();
  });

  it('answers 503 when the room service does not answer and stores nothing (BKG-005, IDM-007)', async () => {
    send.mockReturnValue(throwError(() => new EmptyResponseException(RoomPatternEnum.FIND_BY_ID)));

    expectRpcError(await errorOf(createB1()), 503, ErrorCodeEnum.SERVICE_UNAVAILABLE);
    expectNothingStored();
  });

  it('answers a replay with the stored body and enqueues the same booking id again (IDM-003, CNF-002)', async () => {
    create.mockResolvedValue({ kind: 'replayed', booking });

    await expect(createB1()).resolves.toEqual({ booking, replayed: true });
    expect(enqueue).toHaveBeenCalledTimes(1);
    expect(enqueue).toHaveBeenCalledWith(ID);
  });

  it('answers 422 for a key reused with another body and enqueues nothing (IDM-005)', async () => {
    create.mockResolvedValue({ kind: 'reused' });

    expectRpcError(await errorOf(createB1()), 422, ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED);
    expect(enqueue).not.toHaveBeenCalled();
  });

  it('answers 409 while the key is being processed and enqueues nothing (IDM-006)', async () => {
    create.mockResolvedValue({ kind: 'in-progress' });

    expectRpcError(await errorOf(createB1()), 409, ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS);
    expect(enqueue).not.toHaveBeenCalled();
  });

  it('answers the 503 of a failed enqueue after the booking was stored (CNF-003)', async () => {
    const unavailable = new RpcException({ statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE, message: 'x' });
    enqueue.mockRejectedValue(unavailable);

    await expect(createB1()).rejects.toBe(unavailable);
    expect(create).toHaveBeenCalledTimes(1);
  });
});

